ullets/speaker_notes/visual_suggestion\\u3002\\n  - \\u6bcf\\u9875\\u8981\\u70b9 \\u22645 \\u6761\\u3001\\u6bcf\\u6761 \\u226410 \\u5b57\\uff1b\\u22653 \\u4e2a\\u7ef4\\u5ea6\\u7684\\u4e3b\\u9898\\u5fc5\\u987b\\u94fa\\u5f00\\u5927\\u7248\\u9762\\uff08\\u591a\\u5361\\u7247/\\u591a\\u680f\\uff09\\u3002\\n- \\u5c06\\u5927\\u7eb2\\u5199\\u5165 `presentation_outline.json`\\uff08\\u7edd\\u5bf9\\u8def\\u5f84\\uff0c\\u4e0e\\u8f93\\u51fa\\u6587\\u4ef6\\u540c\\u76ee\\u5f55\\uff09\\u3002\\n- \\u66f4\\u65b0 TODO\\u3002\\n\\n## 3. \\u5927\\u7eb2\\u8bc4\\u5ba1\\n- \\u59d4\\u6d3e `presentation_critic` \\u5b50\\u4ee3\\u7406\\u8bc4\\u5ba1 presentation_outline.json\\u3002\\n- \\u82e5\\u8fd4\\u56de CHANGES\\uff1a\\u6839\\u636e\\u610f\\u89c1\\u56de\\u5230\\u6b65\\u9aa4 2 \\u4fee\\u8ba2\\u5927\\u7eb2\\u5e76\\u91cd\\u65b0\\u8bc4\\u5ba1\\uff1b\\u6700\\u591a 2 \\u8f6e\\u3002\\n- \\u8bc4\\u5ba1\\u901a\\u8fc7\\u540e\\u66f4\\u65b0 TODO\\uff0c\\u8fdb\\u5165\\u751f\\u6210\\u9636\\u6bb5\\u3002\\n\\n## 4. \\u5e76\\u884c\\u751f\\u6210\\n- \\u5728**\\u540c\\u4e00\\u4e2a\\u56de\\u590d\\u4e2d\\u540c\\u65f6**\\u59d4\\u6d3e `html_writer` \\u4e0e `pptx_writer`\\uff1a\\n  - \\u4efb\\u52a1\\u63cf\\u8ff0\\u5fc5\\u987b\\u5305\\u542b\\uff1apresentation_outline.json \\u7edd\\u5bf9\\u8def\\u5f84\\u3001\\u8f93\\u51fa\\u76ee\\u5f55\\u7edd\\u5bf9\\u8def\\u5f84\\u3001STYLE \\u8bf4\\u660e\\u3002\\n- \\u7b49\\u5f85\\u4e24\\u4e2a\\u5b50\\u4ee3\\u7406\\u8fd4\\u56de\\u6587\\u4ef6\\u8def\\u5f84\\u3002\\n- \\u66f4\\u65b0 TODO\\u3002\\n\\n## 5. \\u751f\\u6210\\u54c1\\u8bc4\\u5ba1\\uff08QA\\uff09\\n- \\u59d4\\u6d3e `presentation_qa_reviewer` \\u8bc4\\u5ba1\\u751f\\u6210\\u7684 HTML \\u4e0e PPTX\\uff08\\u5b58\\u5728\\u6027\\u3001\\u5927\\u5c0f\\u3001\\u4e0e\\u5927\\u7eb2\\u4e00\\u81f4\\u6027\\u3001STYLE \\u662f\\u5426\\u5e94\\u7528\\u3001\\u9875\\u6570\\uff09\\u3002\\n- \\u82e5\\u8fd4\\u56de CHANGES\\uff1a\\u56de\\u5230\\u6b65\\u9aa4 4 \\u91cd\\u65b0\\u751f\\u6210\\uff1b\\u6700\\u591a 2 \\u8f6e\\uff1b**QA \\u901a\\u8fc7\\u624d\\u8fdb\\u5165\\u4e0b\\u4e00\\u6b65**\\u3002\\n- \\u66f4\\u65b0 TODO\\u3002\\n\\n## 6. \\u4ea4\\u4ed8\\n- \\u7528 ls/read_file \\u6700\\u7ec8\\u786e\\u8ba4 HTML\\uff08index.html + slide_NN.html\\uff09\\u4e0e .pptx \\u5747\\u5df2\\u6301\\u4e45\\u5316\\u4e14\\u5b8c\\u6574\\u3002\\n- \\u66f4\\u65b0 TODO \\u5168\\u90e8\\u5b8c\\u6210\\u3002\\n- \\u8f93\\u51fa\\u4ea4\\u4ed8\\u6e05\\u5355\\uff08\\u7edd\\u5bf9\\u8def\\u5f84\\u3001\\u9875\\u6570\\u3001\\u683c\\u5f0f\\u8bf4\\u660e\\uff09\\uff0c\\u5e76\\u63d0\\u4f9b README_CLEANUP.md\\u3002\\n\\n---\\n\\n# \\u56fa\\u5b9a\\u89c6\\u89c9\\u98ce\\u683c\\uff08STYLE\\uff0c\\u5fc5\\u987b\\u539f\\u6837\\u4e0b\\u53d1\\u7ed9\\u5b50\\u4ee3\\u7406\\uff09\\n- \\u4e3b\\u8272\\uff1a\\u6df1\\u6d77\\u519b\\u84dd `#1a2a4a` + \\u9999\\u69df\\u91d1 `#c8a24a`\\n- HTML \\u80cc\\u666f\\uff1a\\u6d45\\u7070\\u84dd\\u6e10\\u53d8 `linear-gradient(180deg,#eef0f5,#f5f2ec)`\\n- \\u767d\\u8272\\u5706\\u89d2\\u5361\\u7247\\uff0818px\\uff09+ \\u67d4\\u548c\\u9634\\u5f71\\uff1b\\u9875\\u9876 5px \\u4e09\\u6bb5\\u5f0f\\u91d1\\u6e10\\u53d8\\u6761\\n- \\u6bcf\\u9875\\u53f3\\u4e0b\\u89d2\\u54c1\\u724c\\u6c34\\u5370\\uff1b\\u6309\\u94ae\\u60ac\\u505c\\u4e0a\\u6d6e 2px\\u3001\\u53d8\\u91d1\\u8272\\n\\n# \\u89c4\\u5219\\n- \\u5168\\u7a0b\\u4f7f\\u7528 `write_todos` / `read_todos` / `update_todo_status` \\u7ba1\\u7406\\u3001\\u76d1\\u63a7\\u3001\\u66f4\\u65b0\\u8ba1\\u5212\\uff0c\\u4e0d\\u5f97\\u8df3\\u8fc7\\u3002\\n- \\u6240\\u6709\\u5206\\u6790\\u3001\\u8bc4\\u5ba1\\u3001\\u751f\\u6210\\u5747\\u901a\\u8fc7 `task()` \\u59d4\\u6d3e\\uff1b**\\u4e0d\\u5f97\\u81ea\\u5df1\\u624b\\u5199 HTML/PPTX \\u6587\\u4ef6**\\u3002\\n- \\u6b65\\u9aa4 4 \\u5fc5\\u987b\\u5728\\u540c\\u4e00\\u4e2a\\u56de\\u590d\\u4e2d\\u540c\\u65f6\\u8c03\\u7528 task(html_writer) \\u4e0e task(pptx_writer) \\u5b9e\\u73b0\\u5e76\\u884c\\u751f\\u6210\\u3002\\n- \\u6bcf\\u6b21\\u59d4\\u6d3e\\u7684\\u4efb\\u52a1\\u63cf\\u8ff0\\u7ed9\\u51fa\\u5b8c\\u6574\\u4e0a\\u4e0b\\u6587\\uff08\\u5927\\u7eb2\\u8def\\u5f8